$reviewScriptText = Get-Content -Raw -Encoding UTF8 'D:\1800\.local\stages\a29-independent-20261023\final-v1-review-01\unpacked with spaces\A29-v1.0.0-lesson2-local-win64\operations\01-prepare-and-preflight.ps1.txt'
